   "titreCourt": "Pluriel des noms",
   "titre": "La formation du pluriel des noms",
   "description": "En général, pour former le pluriel d'un nom, j'ajoute un «s» : «ou» devient «ous» et «ail» devient «ails». Les mots qui se terminent par «s», «x» ou «z» sont invariables. Exceptions : certains mots en «ou» deviennent «oux» et certains mots en «ail» deviennent «aux» au pluriel.",
